import assert from 'node:assert';
import { describe, it } from 'vitest';
import type { CardRow } from '../types';
import type { ParsedListEntry } from './parseList';
import { validateDeck } from './deckValidation';

let counter = 0;
function makeCard(overrides: Partial<CardRow> = {}): CardRow {
  const name = overrides.name ?? `Test Card ${counter++}`;
  return {
    oracle_id: overrides.oracle_id ?? name,
    name,
    name_lower: name.toLowerCase(),
    mana_cost: null,
    cmc: 0,
    type_line: 'Creature ΓÇö Human',
    oracle_text: null,
    colors: '[]',
    color_identity: '[]',
    keywords: '[]',
    creature_types: '[]',
    power: '1',
    toughness: '1',
    scryfall_uri: null,
    partner_ability: null,
    partner_target: null,
    is_background: 0,
    legality_commander: 'legal',
    game_changer: 0,
    is_legendary: 0,
    is_commander_eligible: 0,
    is_changeling: 0,
    image_uri: null,
    back_image_uri: null,
    back_name: null,
    ...overrides,
  };
}

function entry(name: string, quantity = 1): ParsedListEntry {
  return { name, quantity, raw: name };
}

function nameMapOf(cards: CardRow[]): Map<string, CardRow> {
  return new Map(cards.map((c) => [c.name_lower, c]));
}

function eligibleCommander(overrides: Partial<CardRow> = {}): CardRow {
  return makeCard({ is_legendary: 1, is_commander_eligible: 1, ...overrides });
}

describe('validateDeck ΓÇö deck size (903.5a)', () => {
  it('exactly 100 cards with a legal commander is valid', () => {
    const commander = eligibleCommander({ name: 'Test Commander', color_identity: '["W"]' });

    const result = validateDeck(
      [entry('Test Commander'), entry('Plains', 99)],
      nameMapOf([commander, makeCard({ name: 'Plains', color_identity: '["W"]' })]),
      [commander],
      [],
    );

    assert.strictEqual(result.isValid, true);
    assert.strictEqual(result.deckSize.total, 100);
    assert.strictEqual(result.deckSize.isValid, true);
  });

  it('99 cards is invalid ΓÇö CR 903.5a sets both the minimum and the maximum at 100', () => {
    const commander = eligibleCommander({ name: 'Test Commander', color_identity: '["W"]' });

    const result = validateDeck(
      [entry('Test Commander'), entry('Plains', 97)],
      nameMapOf([commander, makeCard({ name: 'Plains', color_identity: '["W"]' })]),
      [commander],
      [],
    );

    assert.strictEqual(result.isValid, false);
    assert.strictEqual(result.deckSize.total, 98);
    assert.strictEqual(result.deckSize.isValid, false);
  });

  it('a banned card still occupies a deck slot in the count', () => {
    const commander = eligibleCommander({ name: 'Test Commander', color_identity: '["W"]' });
    const banned = makeCard({ name: 'Banned Card', legality_commander: 'banned' });

    // 99 legal + 1 banned pasted = a 100-card deck. The count must read 100 ΓÇö
    // the fix here is "swap the banned card", and a count of 99 would tell the
    // player to add one instead. Regression for the auditor's plan, which only
    // summed `submitted`.
    const result = validateDeck(
      [entry('Test Commander'), entry('Plains', 98), entry('Banned Card')],
      nameMapOf([
        commander,
        makeCard({ name: 'Plains', color_identity: '["W"]' }),
        banned,
      ]),
      [commander],
      [],
    );

    assert.strictEqual(result.deckSize.total, 100);
    assert.strictEqual(result.deckSize.isValid, true);
    assert.deepStrictEqual(result.legality.banned, ['Banned Card']);
    assert.strictEqual(result.isValid, false);
  });

  it('an unparseable card still occupies a deck slot in the count', () => {
    const commander = eligibleCommander({ name: 'Test Commander', color_identity: '["W"]' });

    const result = validateDeck(
      [entry('Test Commander'), entry('Plains', 97), entry('Not A Real Card', 2)],
      nameMapOf([commander, makeCard({ name: 'Plains', color_identity: '["W"]' })]),
      [commander],
      [],
    );

    assert.strictEqual(result.deckSize.total, 100);
    assert.deepStrictEqual(result.legality.notFound, ['Not A Real Card']);
    assert.strictEqual(result.isValid, false);
  });
});

describe('validateDeck ΓÇö color identity (903.4)', () => {
  it('decodes the JSON-string color_identity column before checking (parseJsonArray)', () => {
    const commander = eligibleCommander({ name: 'Test Commander', color_identity: '["U"]' });
    // The stored column is a JSON string, not an array. Passing it straight to
    // @mtg/rules would iterate its characters instead of its colors.
    const offIdentity = makeCard({ name: 'Illegal Card', color_identity: '["U","W"]' });
    const plainsCount = 97;

    const result = validateDeck(
      [entry('Test Commander'), entry('Illegal Card'), entry('Island', plainsCount)],
      nameMapOf([
        commander,
        offIdentity,
        makeCard({ name: 'Island', color_identity: '["U"]' }),
      ]),
      [commander],
      [],
    );

    assert.strictEqual(result.isValid, false);
    assert.deepStrictEqual(result.colorIdentity.violations, [
      { name: 'Illegal Card', color_identity: ['U', 'W'], quantity: 1 },
    ]);
  });

  it('a colorless deck is vacuously within any identity', () => {
    const commander = eligibleCommander({ name: 'Test Commander', color_identity: '["W"]' });

    const result = validateDeck(
      [entry('Test Commander'), entry('Artifact Land', 99)],
      nameMapOf([commander, makeCard({ name: 'Artifact Land', color_identity: '[]' })]),
      [commander],
      [],
    );

    assert.strictEqual(result.colorIdentity.violations.length, 0);
    assert.strictEqual(result.isValid, true);
  });
});

describe('validateDeck ΓÇö commander unit legality (903.3 / 702.124)', () => {
  it('a card that is not commander-eligible cannot be named commander', () => {
    const notEligible = makeCard({ name: 'Sol Ring', color_identity: '[]' });

    const result = validateDeck(
      [entry('Plains', 99)],
      nameMapOf([notEligible, makeCard({ name: 'Plains', color_identity: '["U"]' })]),
      [notEligible],
      [],
    );

    assert.strictEqual(result.commander.eligible, false);
    assert.strictEqual(result.commander.pairingLegal, false);
    assert.strictEqual(result.isValid, false);
  });

  it('a legal Partner pair is one commander unit with the union identity (702.124e)', () => {
    const a = eligibleCommander({
      name: 'Partner A',
      color_identity: '["W"]',
      partner_ability: 'partner',
      creature_types: '["Creature"]',
    });
    const b = eligibleCommander({
      name: 'Partner B',
      color_identity: '["U"]',
      partner_ability: 'partner',
      creature_types: '["Creature"]',
    });

    const result = validateDeck(
      [entry('Partner A'), entry('Partner B'), entry('Plains', 98)],
      nameMapOf([
        a,
        b,
        makeCard({ name: 'Plains', color_identity: '["U"]' }),
      ]),
      [a, b],
      [],
    );

    assert.strictEqual(result.commander.eligible, true);
    assert.strictEqual(result.commander.pairingLegal, true);
    assert.deepStrictEqual(new Set(result.commander.colorIdentity), new Set(['W', 'U']));
    assert.strictEqual(result.isValid, true);
  });

  it('two legendary cards without a pairing ability are not a legal unit', () => {
    const a = eligibleCommander({ name: 'Legend A', color_identity: '["W"]' });
    const b = eligibleCommander({ name: 'Legend B', color_identity: '["U"]' });

    const result = validateDeck(
      [entry('Legend A'), entry('Legend B'), entry('Plains', 98)],
      nameMapOf([a, b, makeCard({ name: 'Plains', color_identity: '["U"]' })]),
      [a, b],
      [],
    );

    assert.strictEqual(result.commander.pairingLegal, false);
    assert.strictEqual(result.isValid, false);
  });

  it('a Background companion needs the legal Background to pair', () => {
    const chooser = eligibleCommander({
      name: 'Commander with Background',
      color_identity: '["W"]',
      partner_ability: 'choose_background',
      creature_types: '["Creature"]',
    });
    const background = makeCard({
      name: 'A Legal Background',
      color_identity: '["W"]',
      partner_ability: null,
      is_background: 1,
    });

    const result = validateDeck(
      [entry('Commander with Background'), entry('A Legal Background'), entry('Plains', 98)],
      nameMapOf([
        chooser,
        background,
        makeCard({ name: 'Plains', color_identity: '["W"]' }),
      ]),
      [chooser, background],
      [background],
    );

    assert.strictEqual(result.commander.pairingLegal, true);
    assert.strictEqual(result.isValid, true);
  });
});

/**
 * Which "commander units" ΓÇö solo cards, or legal pairs ΓÇö can be built from a
 * pool of eligible candidates under the Partner-family of abilities.
 */

export type PartnerAbility =
  | 'partner'
  | 'partner_with'
  | 'partner_suffix'
  | 'friends_forever'
  | 'choose_background'
  | 'doctors_companion'
  | null;

/**
 * The slice of a card these rules need. `creature_types` matches Scryfall
 * bulk data's own JSON-encoded-string column shape (the common storage
 * form for it) rather than a parsed array ΓÇö keeping this the same shape a
 * caller's own card type already has (e.g. commander-recommender's
 * `CardRow`) means `buildCommanderUnits` can return the caller's exact
 * card objects unmodified, not a reshaped copy that would then mismatch
 * every other place those same objects flow through.
 */
export interface PartnerCardLike {
  oracle_id: string;
  name_lower: string;
  type_line?: string | null;
  creature_types: string;
  partner_ability: PartnerAbility;
  partner_target: string | null;
}

/** Decodes creature_types' JSON-string-array shape, tolerating a malformed value. */
function parseCreatureTypes(json: string): string[] {
  try {
    const parsed = JSON.parse(json);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

/**
 * A commander as actually played: one card, or two under a Partner-family
 * ability (702.124). Every card in `cards` is jointly "the commander" ΓÇö
 * there's no primary/secondary in the rules (702.124e), so this is an array
 * rather than a "main card + optional partner" shape.
 */
export interface CommanderUnit<TCard extends PartnerCardLike = PartnerCardLike> {
  cards: TCard[];
}

function creatureTypeSet(card: PartnerCardLike): Set<string> {
  return new Set(parseCreatureTypes(card.creature_types));
}

function setEquals(a: Set<string>, b: Set<string>): boolean {
  return a.size === b.size && [...a].every((item) => b.has(item));
}

/** Stable id for a unit, used to dedupe pairs regardless of which card was found first. */
export function unitKey(unit: CommanderUnit): string {
  return unit.cards
    .map((c) => c.oracle_id)
    .sort()
    .join('+');
}

/**
 * Builds every legal "commander unit" from the eligible candidate pool: one
 * per solo card, plus one per valid Partner/Partner-with/PartnerΓÇösuffix/
 * Friends-forever/Choose-a-Background/Doctor's-companion pair.
 *
 * Pairing is grouped by ability variant rather than a blind cross-product
 * over every candidate ΓÇö with an eligible pool in the tens to low hundreds,
 * pairing only within (or against) the relevant sub-groups keeps this cheap
 * enough to run per request, which is what was asked for. Different partner
 * variants never combine with each other (702.124f) ΓÇö a plain-Partner card
 * cannot pair with a Partner-with card, for instance ΓÇö which pairing only
 * within each group already guarantees.
 *
 * A card with a partner ability still gets its own solo unit too: every
 * variant here is optional (903.3 / 702.124a), so a Partner card is a
 * perfectly legal commander by itself. The one exception is Background
 * enchantments, which never appear as a solo candidate in the first place
 * (they're not a creature/Vehicle/Spacecraft, so a caller's own candidate
 * pool already excludes them) and are only ever reached here as a pairing
 * target.
 */
export function buildCommanderUnits<TCard extends PartnerCardLike>(
  candidates: TCard[],
  backgrounds: TCard[],
): CommanderUnit<TCard>[] {
  const units: CommanderUnit<TCard>[] = candidates.map((card) => ({ cards: [card] }));
  const seenPairs = new Set<string>();

  function addPair(a: TCard, b: TCard): void {
    if (a.oracle_id === b.oracle_id) return;
    const key = [a.oracle_id, b.oracle_id].sort().join('+');
    if (seenPairs.has(key)) return;
    seenPairs.add(key);
    units.push({ cards: [a, b] });
  }

  function pairAllWithin(group: TCard[]): void {
    for (let i = 0; i < group.length; i++) {
      // Both i and j are always within [0, group.length) by the loop bounds.
      for (let j = i + 1; j < group.length; j++) addPair(group[i]!, group[j]!);
    }
  }

  const byAbility = (ability: PartnerAbility) =>
    candidates.filter((c) => c.partner_ability === ability);

  // Plain Partner: any two.
  pairAllWithin(byAbility('partner'));

  // PartnerΓÇö[text]: only within the same suffix group.
  const suffixGroups = new Map<string, TCard[]>();
  for (const card of byAbility('partner_suffix')) {
    const key = card.partner_target ?? '';
    const group = suffixGroups.get(key);
    if (group) group.push(card);
    else suffixGroups.set(key, [card]);
  }
  for (const group of suffixGroups.values()) pairAllWithin(group);

  // Partner with [Name]: symmetric named pairing ΓÇö each card must name the
  // other (702.124j), not just be named by it.
  const byNameLower = new Map(candidates.map((c) => [c.name_lower, c]));
  for (const card of byAbility('partner_with')) {
    const target = card.partner_target ? byNameLower.get(card.partner_target) : undefined;
    if (target?.partner_ability === 'partner_with' && target.partner_target === card.name_lower) {
      addPair(card, target);
    }
  }

  // Friends forever: any two. Restricted to creatures by the rule (702.124k),
  // which every real friends-forever card already satisfies as printed ΓÇö
  // checked anyway rather than assumed, since nothing stops a future card
  // from breaking that pattern.
  pairAllWithin(
    byAbility('friends_forever').filter((c) => (c.type_line ?? '').includes('Creature')),
  );

  // Choose a Background: the companion card ├ù every legal legendary Background.
  for (const chooser of byAbility('choose_background')) {
    for (const background of backgrounds) addPair(chooser, background);
  }

  // Doctor's companion: the companion card ├ù any legendary creature whose
  // creature types are *exactly* Time Lord and Doctor ΓÇö no other subtypes.
  const timeLordDoctor = new Set(['Time Lord', 'Doctor']);
  const doctors = candidates.filter((c) => setEquals(creatureTypeSet(c), timeLordDoctor));
  for (const companion of byAbility('doctors_companion')) {
    for (const doctor of doctors) addPair(companion, doctor);
  }

  return units;
}
